package run.halo.starter;
import java.util.concurrent.atomic.AtomicInteger;
import org.junit.jupiter.api.Test;
import org.springframework.http.*;
import org.springframework.web.reactive.function.client.*;
import reactor.core.publisher.Mono;
import java.util.Map;
import static org.mockito.Mockito.*;
import static org.junit.jupiter.api.Assertions.*;
class OfficialAccountApiTest {
 @Test void protectedImagesReceiveArticleRefererWithoutCredentials(){var config=mock(OfficialAccountConfig.class);var calls=new AtomicInteger();var web=WebClient.builder().exchangeFunction(r->{assertEquals("https://blog.example/archives/article",r.headers().getFirst(HttpHeaders.REFERER));assertNull(r.headers().getFirst(HttpHeaders.AUTHORIZATION));assertNull(r.headers().getFirst(HttpHeaders.COOKIE));calls.incrementAndGet();return Mono.just(ClientResponse.create(HttpStatus.OK).header("Content-Type","image/jpeg").body("image").build());}).build();var api=new OfficialAccountApi(config,web,web);assertNotNull(api.image("https://cdn.example/image.jpg","https://blog.example/archives/article").block());assertEquals(1,calls.get());assertThrows(IllegalArgumentException.class,()->api.image("https://cdn.example/image.jpg","http://localhost/").block());assertEquals(1,calls.get());}
 @Test void imageMultipartHasExplicitBoundaryAndUnmodifiedBinary(){byte[] image={0,1,-1,2};byte[] body=OfficialAccountApi.multipart(image,"test-boundary");String ascii=new String(body,java.nio.charset.StandardCharsets.ISO_8859_1);assertTrue(ascii.startsWith("--test-boundary\r\n"));assertTrue(ascii.contains("name=\"media\"; filename=\"frame-image.jpg\""));assertTrue(ascii.endsWith("\r\n--test-boundary--\r\n"));int offset=ascii.indexOf("\r\n\r\n")+4;assertArrayEquals(image,java.util.Arrays.copyOfRange(body,offset,offset+image.length));}
 @Test void tokenIsCachedAndDraftResponseIsNotTreatedAsPublished(){var config=mock(OfficialAccountConfig.class);when(config.credentials("account")).thenReturn(Mono.just(new OfficialAccountConfig.Credentials("account","private-secret")));var tokens=new AtomicInteger();var web=WebClient.builder().baseUrl("https://api.weixin.qq.com").exchangeFunction(request->{boolean token=request.url().getPath().endsWith("stable_token");if(token)tokens.incrementAndGet();return Mono.just(ClientResponse.create(HttpStatus.OK).header("Content-Type","application/json").body(token?"{\"access_token\":\"private-token\",\"expires_in\":7200}":"{\"media_id\":\"draft-media\"}").build());}).build();var api=new OfficialAccountApi(config,web,web);var first=api.json("account","/cgi-bin/draft/add",Map.of("articles",java.util.List.of())).block();api.token("account").block();assertEquals(1,tokens.get());assertEquals("draft-media",first.path("media_id").asText());assertFalse(first.has("publish_id"));}
 @Test void networkFailureNeverLeaksCredentialsOrRequestUri(){var config=mock(OfficialAccountConfig.class);when(config.credentials("account")).thenReturn(Mono.just(new OfficialAccountConfig.Credentials("account","private-secret")));var web=WebClient.builder().baseUrl("https://api.weixin.qq.com").exchangeFunction(r->Mono.error(new IllegalStateException("https://api.weixin.qq.com/?access_token=private-token&secret=private-secret"))).build();var api=new OfficialAccountApi(config,web,web);var error=assertThrows(OfficialAccountApi.Failure.class,()->api.token("account").block());assertFalse(error.toString().contains("private-token"));assertFalse(error.toString().contains("private-secret"));assertNull(error.getCause());}
 @Test void permissionAndWhitelistErrorsAreActionableButSanitized(){assertTrue(OfficialAccountApi.failure(40164).getMessage().contains("白名单"));assertTrue(OfficialAccountApi.failure(48001).getMessage().contains("权限"));assertFalse(OfficialAccountApi.failure(48001).ambiguous());}
}
